{{-- Owner 16 Nov 2026: goods of an EARLIER order that came back with this parcel. window.pastRetOpen(carrierOrderId, onDone) opens the popup. Stock changes only on "Confirm received". --}}
@once
<script>
window.pastRetOpen=function(cid,onDone){
  function esc(s){var d=document.createElement('div');d.textContent=s==null?'':s;return d.innerHTML}
  var T=(document.querySelector('meta[name=csrf-token]')||{}).content||'',tok='pr'+Date.now().toString(36)+Math.random().toString(36).slice(2,12);
  fetch('/admin/orders/'+cid+'/past-return/options',{credentials:'same-origin',headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(function(j){
    var w=document.createElement('div');w.style.cssText='position:fixed;inset:0;background:rgba(15,31,61,.45);z-index:10000;display:flex;align-items:center;justify-content:center';
    var h='<div style="background:#fff;border-radius:12px;padding:16px;width:min(760px,96vw);max-height:92vh;overflow:auto;font-size:13px;color:#0B1B33"><h3 style="margin:0 0 4px;font-size:16px">আগের অর্ডারের পণ্য ফেরত</h3><p style="font-size:12px;color:#475467;margin:4px 0 10px">এই পার্সেলের সঙ্গে কাস্টমার আগের কোনো অর্ডারের পণ্য ফেরত দিলে এখানে নিন। রিটার্নটি মূল অর্ডারের নামে লেখা হবে; এই পার্সেলের অর্ডার বদলাবে না। পণ্য হাতে পেয়ে যাচাই করার পর "গ্রহণ নিশ্চিত" চাপুন, তখনই স্টকে যোগ হবে।</p>';
    if(!j.success){h+='<div style="color:#B42318">'+esc(j.message||'Could not load')+'</div>'}
    else if(!j.orders.length){h+='<div style="color:#475467">এই কাস্টমারের এমন কোনো আগের অর্ডার নেই যার পণ্য এখনো কাস্টমারের কাছে আছে।</div>'}
    else j.orders.forEach(function(o){h+='<div style="border:1px solid #E5E7EB;border-radius:10px;margin-bottom:8px;overflow:hidden"><div style="background:#F9FAFB;padding:7px 10px;font-weight:700">অর্ডার '+esc(o.invoice)+' <span style="font-weight:500;color:#475467">· '+esc(o.date)+' · '+esc(o.status)+'</span></div>';
      o.items.forEach(function(i){var u=i.has_packets?'প্যাকেট':'টি',full=i.left<=0;h+='<div class="prR" data-id="'+i.id+'" data-pack="'+i.pack+'" data-left="'+i.left+'" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:8px 10px;border-top:1px solid #F2F4F7'+(full?';opacity:.55':'')+'"><div style="flex:1;min-width:200px"><b>'+esc(i.name)+'</b><div style="font-size:12px;color:#475467">বিক্রি '+i.sold+' '+u+(i.has_packets?' ('+i.qty+' কার্টন × '+i.pack+')':'')+' · আগে ফেরত '+i.taken+' · <b style="color:'+(full?'#B42318':'#067647')+'">ফেরতযোগ্য '+i.left+' '+u+'</b></div></div>'+
        (full?'':'<label style="font-size:12px;display:flex;gap:4px;align-items:center">'+(i.has_packets?'পুরো কার্টন':'ভালো')+'<input type="number" class="prC" min="0" value="0" style="width:62px"></label>'+(i.has_packets?'<label style="font-size:12px;display:flex;gap:4px;align-items:center">খুচরা প্যাকেট<input type="number" class="prP" min="0" value="0" style="width:62px"></label>':'')+'<label style="font-size:12px;display:flex;gap:4px;align-items:center">ক্ষতিগ্রস্ত'+(i.has_packets?' প্যাকেট':'')+'<input type="number" class="prD" min="0" value="0" style="width:62px"></label>')+'</div>'});h+='</div>'});
    h+='<div id="prE" style="color:#B42318;font-size:12.5px;margin-top:6px"></div><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px"><button type="button" class="g" id="prX">বন্ধ করুন</button>'+(j.success&&j.orders.length?'<button type="button" id="prS" style="background:#5B3FA6;color:#fff">গ্রহণ নিশ্চিত</button>':'')+'</div></div>';
    w.innerHTML=h;document.body.appendChild(w);w.querySelector('#prX').onclick=function(){w.remove()};
    var s=w.querySelector('#prS');if(s)s.onclick=function(){var lines=[],bad='';w.querySelectorAll('.prR').forEach(function(r){var c=r.querySelector('.prC');if(!c)return;var ca=+c.value||0,pk=+((r.querySelector('.prP')||{}).value||0),dm=+((r.querySelector('.prD')||{}).value||0),n=ca*(+r.dataset.pack)+pk+dm;if(n<=0)return;if(n>+r.dataset.left)bad='একটি পণ্যে ফেরতযোগ্য পরিমাণের বেশি লেখা হয়েছে।';lines.push({item:+r.dataset.id,cartons:ca,packets:pk,damaged:dm})});
      var e=w.querySelector('#prE');if(bad){e.textContent=bad;return}if(!lines.length){e.textContent='অন্তত একটি পরিমাণ লিখুন।';return}
      s.disabled=true;e.textContent='';fetch('/admin/orders/'+cid+'/past-return',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':T,'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify({token:tok,lines:lines})}).then(function(r){return r.json()}).then(function(k){if(k.success){w.remove();if(onDone)onDone(k.message||'Received');else location.reload()}else{s.disabled=false;e.textContent=k.message||'Failed'}}).catch(function(){s.disabled=false;e.textContent='সংযোগে সমস্যা। আবার "গ্রহণ নিশ্চিত" চাপুন; একই রিটার্ন দুবার যোগ হবে না।'})}
  }).catch(function(){alert('Could not load earlier orders.')})};
</script>
@endonce
